class PathSolver {
    int N;
    vector<vector<pair<int, int>>> graph;
public:
    PathSolver(int n) : N(n), graph(n + 1) {}
    void addEdge(int u, int v, int w) { graph[u].push_back({v, w}); }
    vector<int> findShortestPath(int start, int end) {
        vector<int> dist(N + 1, INT_MAX);
        dist[start] = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, start});
        while (!pq.empty()) {
            int w = -pq.top().first;
            int u = pq.top().second;
            pq.pop();
            if (u == end) return dist;
            if (dist[u] < w) continue;
            for (auto &edge : graph[u]) {
                int v = edge.first, w2 = w + edge.second;
                if (dist[v] > w2) {
                    dist[v] = w2;
                    pq.push({-w2, v});
                }
            }
        }
        return dist;
    }
    void run() {
        int n, e, s, u, v, w;
        scanf("%d%d", &n, &e);
        PathSolver ps(n);
        scanf("%d", &s);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            ps.addEdge(u, v, w);
        }
        vector<int> ans = ps.findShortestPath(s, N);
        for (int i = 1; i <= n; i++) {
            if (ans[i] >= INT_MAX) printf("INF\n");
            else printf("%d\n", ans[i]);
        }
    }
};

