    vector<vector<pair<int, int>>> edges;
public:
    SpanningTree(int n) : N(n), edges(n + 1) {}
    void insert(int u, int v, int w) { edges[u].push_back({v, w}); }
    void compute(long long &total) {
        vector<int> dist(N + 1, INT_MAX);
        vector<bool> inTree(N + 1, false);
        dist[1] = 0;
        total = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, 1});
        for (int i = 0; i < N; i++) {
            int u = -1, minDist = INT_MAX;
            while (!pq.empty()) {
                u = pq.top().second;
                pq.pop();
                if (!inTree[u]) break;
            }
            if (u == -1 || inTree[u]) break;
            inTree[u] = true;
            total += dist[u];
            for (auto &edge : edges[u]) {
                int v = edge.first, w = edge.second;
                if (!inTree[v] && dist[v] > w) {
